      "3": "Increases the wearer's SPD by 24%. When the wearer uses Basic ATK, Skill, or Ultimate, consumes all allies' HP equal to 1.5% of their current HP, and after the next attack of the wearer's memosprite, enables it to additionally deal 1 instance of Additional DMG equal to 375.0% of the total consumed HP to the attacked target, with the damage type based on the memosprite's type. Then, the total consumed HP is reset. When the wearer's memosprite uses Memosprite Skill, increases the DMG taken by all enemies by 27.0%, lasting for 2 turn(s). Effects of the same type cannot stack.",
      "4": "Increases the wearer's SPD by 27%. When the wearer uses Basic ATK, Skill, or Ultimate, consumes all allies' HP equal to 1.8% of their current HP, and after the next attack of the wearer's memosprite, enables it to additionally deal 1 instance of Additional DMG equal to 437.5% of the total consumed HP to the attacked target, with the damage type based on the memosprite's type. Then, the total consumed HP is reset. When the wearer's memosprite uses Memosprite Skill, increases the DMG taken by all enemies by 31.5%, lasting for 2 turn(s). Effects of the same type cannot stack.",
      "5": "Increases the wearer's SPD by 30%. When the wearer uses Basic ATK, Skill, or Ultimate, consumes all allies' HP equal to 2.0% of their current HP, and after the next attack of the wearer's memosprite, enables it to additionally deal 1 instance of Additional DMG equal to 500.0% of the total consumed HP to the attacked target, with the damage type based on the memosprite's type. Then, the total consumed HP is reset. When the wearer's memosprite uses Memosprite Skill, increases the DMG taken by all enemies by 36.0%, lasting for 2 turn(s). Effects of the same type cannot stack."
